    }

    #heroStatsBar .stats-value {
        color: #ffffff;
        font-size: 15px;
        font-weight: 700;
        line-height: 1.3;
        margin: 3px 0 0;
        font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
        letter-spacing: -0.2px;
        white-space: nowrap;
    }

    @media (max-width: 1199px) {
        #heroStatsBar .stats-row {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 20px 30px;
        }
        #heroStatsBar .stats-item {
            justify-content: flex-start;
        }
    }

    @media (max-width: 640px) {
        #heroStatsBar {
            padding: 16px 0 !important;
        }
        #heroStatsBar .stats-row {
            grid-template-columns: 1fr;
            gap: 16px;
        }
        #heroStatsBar .stats-icon {
            width: 38px;
            height: 38px;
        }
        #heroStatsBar .stats-label {
            font-size: 12px;
        }
        #heroStatsBar .stats-value {
            font-size: 14px;
            white-space: normal;
        }
    }
    </style>

