    <!-- Career Tabs Script and Style -->
    <style>
    .career-section .tab-btn {
        cursor: pointer !important;
        transition: background-color 0.25s ease, color 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease !important;
    }
    .career-section .tab-btn:hover:not(.active) {
        background-color: rgba(3, 4, 94, 0.06) !important;
    }
    .career-section .tab-content-item {
        transition: opacity 0.35s ease-in-out !important;
    }
    </style>
    <script>
    (function() {
        function initCareerTabs() {
            const tabs = document.querySelectorAll(".career-section .tab-btn");
            const contents = document.querySelectorAll(".career-section .tab-content-item");

            if (!tabs.length) return;

            tabs.forEach(function(tab) {
                tab.addEventListener("click", function(e) {
                    e.preventDefault();
                    tabs.forEach(function(btn) { btn.classList.remove("active"); });
                    this.classList.add("active");

                    const target = this.getAttribute("data-tab");
                    contents.forEach(function(content) { content.classList.remove("active"); });

                    const targetEl = document.getElementById(target);
                    if (targetEl) {
                        targetEl.classList.add("active");
                    }
                });
            });
        }

        if (document.readyState === "loading") {
            document.addEventListener("DOMContentLoaded", initCareerTabs);
        } else {
            initCareerTabs();
        }
    })();
    </script>
    
