    <!-- Self-contained Tab Switching Script for Career Services -->
    <script>
    (function initCareerServicesTabs() {
        function setup() {
            const tabs = document.querySelectorAll('#master7 .career-nav-tabs .nav-link');
            const panes = document.querySelectorAll('#master7 .career-tab-content .tab-pane');
            if (!tabs.length) return;

            tabs.forEach(tab => {
                tab.addEventListener('click', function(e) {
                    e.preventDefault();
                    const targetId = this.getAttribute('href') || this.getAttribute('data-bs-target');
                    
                    tabs.forEach(t => t.classList.remove('active'));
                    this.classList.add('active');

                    panes.forEach(pane => {
                        pane.classList.remove('show', 'active');
                    });

                    const targetPane = document.querySelector(targetId);
                    if (targetPane) {
                        targetPane.classList.add('show', 'active');
                    }
                });
            });
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', setup);
        } else {
            setup();
        }
    })();
    </script>



