            radial-gradient(circle at 5% 15%, rgba(91, 85, 232, 0.88) 0%, rgba(91, 85, 232, 0) 45%),
            radial-gradient(circle at 95% 85%, rgba(72, 185, 139, 0.78) 0%, rgba(72, 185, 139, 0) 45%),
