    }

    .upcoming-app.application-deadline .deadline-bg-text span:nth-child(4) {
        opacity: 0.12 !important;
    }

    /* Centered Overlapping Hourglass - Perfectly Sized to Heading */
    .upcoming-app.application-deadline .deadline-hourglass-box {
        position: absolute !important;
