        min-height: 270px;
        margin: 0;
        padding: 18px 18px 20px;
        background: #ffffff;
        border: none;
        border-radius: 8px;
        border-bottom: 5px solid #F5AA35;
        box-shadow: 0 4px 14px rgba(0, 0, 0, 0.08);
        display: flex;
        flex-direction: column;
        justify-content: flex-start;
        text-align: left;
        overflow: hidden;
    }

    #testimonials.review .testimonials-swiper .swiper-slide .item .details {
        display: flex;
        align-items: center;
        justify-content: flex-start;
        gap: 12px;
        margin-bottom: 12px;
    }

    #testimonials.review .testimonials-swiper .swiper-slide .item .details .image {
        width: 60px;
        height: 60px;
        min-width: 60px;
        flex-shrink: 0;
        border-radius: 50%;
        background: #f3f4f6;
        padding: 4px;
        overflow: hidden;
        display: flex;
        align-items: center;
        justify-content: center;
    }

    #testimonials.review .testimonials-swiper .swiper-slide .item .details .image img {
        width: 100%;
        height: 100%;
        border-radius: 50%;
        object-fit: cover;
        display: block;
    }

    #testimonials.review .testimonials-swiper .swiper-slide .item .details .namestar {
        display: flex;
        flex-direction: column;
        align-items: flex-start;
        justify-content: center;
        gap: 5px;
        min-width: 0;
    }

    #testimonials.review .testimonials-swiper .swiper-slide .item .details .namestar .name {
        color: #1A1A1A;
        font-size: 19px;
        font-weight: 700;
        line-height: 1.25;
        margin: 0;
        text-align: left;
    }

    #testimonials.review .testimonials-swiper .swiper-slide .item .details .namestar img {
        height: 15px;
        width: auto;
        max-width: 96px;
        object-fit: contain;
        display: block;
    }

    #testimonials.review .testimonials-swiper .swiper-slide .item .content {
        margin-top: 0;
        flex: 1;
    }

    #testimonials.review .testimonials-swiper .swiper-slide .item .content p {
        color: #333333;
        font-size: 16px;
        font-weight: 400;
        line-height: 1.55;
        margin: 0;
        text-align: left;
        word-wrap: break-word;
        overflow-wrap: break-word;
    }

    #testimonials.review .testimonials-pagination {
        position: static;
        width: 100%;
        margin: 16px auto 0;
        padding: 4px 0;
        display: flex;
        justify-content: center;
        align-items: center;
        gap: 8px;
    }

    #testimonials.review .testimonials-pagination .swiper-pagination-bullet {
        width: 7px;
        height: 7px;
        border-radius: 50%;
        background: #F5AA35;
        opacity: 1;
        margin: 0;
        padding: 0;
        border: none;
        box-shadow: none;
        cursor: pointer;
        box-sizing: content-box;
        transition: transform 0.2s ease, background-color 0.2s ease;
    }

    #testimonials.review .testimonials-pagination .swiper-pagination-bullet-active {
        width: 8px;
        height: 8px;
        background: #F5AA35;
        border: 3px solid #ffffff;
        box-shadow: 0 0 0 1.5px #113563;
        margin: 0 3px;
        padding: 0;
    }

    @media (max-width: 1199.98px) {
        #testimonials.review .testimonials-swiper .swiper-slide .item {
            min-height: 265px;
        }
    }

    @media (max-width: 767.98px) {
        #testimonials.review {
            padding: 36px 0 32px;
        }

        #testimonials.review > .container-fluid {
            padding: 0 16px;
        }

        #testimonials.review .heading {
            font-size: 27px;
        }

        #testimonials.review .tagline {
            font-size: 16px;
            margin-bottom: 20px;
        }

        #testimonials.review .testimonials-swiper .swiper-slide .item {
            min-height: auto;
            padding: 16px 16px 18px;
        }

        #testimonials.review .testimonials-swiper .swiper-slide .item .details .image {
            width: 56px;
            height: 56px;
            min-width: 56px;
        }

        #testimonials.review .testimonials-swiper .swiper-slide .item .details .namestar .name {
            font-size: 17.5px;
        }

        #testimonials.review .testimonials-swiper .swiper-slide .item .content p {
            font-size: 15px;
            text-align: left;
        }
    }
    </style>

    <style>
    /* Reviews Section Self-Contained Styles & Visibility Guarantee */
    #reviews-section {
        padding: 40px 0 35px;
        background: #ffffff;
        display: block !important;
        visibility: visible !important;
        opacity: 1 !important;
        position: relative;
    }
    #reviews-section .reviews-top-bar,
    #reviews-section .reviews-carousel-container {
        opacity: 1 !important;
        transform: none !important;
        visibility: visible !important;
    }
    #reviews-section .reviews-top-bar {
        display: flex;
        align-items: flex-start;
        justify-content: space-between;
        gap: 20px;
        margin-bottom: 24px;
    }
    #reviews-section .reviews-title {
        font-size: 28px;
        font-weight: 700;
        color: #19335A;
        margin: 0 0 8px 0;
        line-height: 1.25;
        letter-spacing: -0.3px;
    }
    #reviews-section .reviews-subtitle {
        font-size: 15px;
        color: #64748b;
        margin: 0;
        line-height: 1.5;
    }
    #reviews-section .reviews-nav-arrows {
        display: flex;
        align-items: center;
        gap: 12px;
        flex-shrink: 0;
    }
    #reviews-section .review-nav-btn {
        width: 44px;
        height: 44px;
        border-radius: 50%;
        display: flex;
        align-items: center;
        justify-content: center;
        cursor: pointer;
        transition: all 0.2s ease;
        padding: 0;
    }
    #reviews-section .review-nav-btn.prev {
        background: #E5A11F;
        border: 1.5px solid #E5A11F;
        color: #ffffff;
    }
    #reviews-section .review-nav-btn.prev:hover {
        background-color: #d18f15;
        transform: scale(1.05);
    }
    #reviews-section .review-nav-btn.next {
        background: #19335A;
        border: 1.5px solid #19335A;
        color: #ffffff;
    }
    #reviews-section .review-nav-btn.next:hover {
        background-color: #112543;
        transform: scale(1.05);
    }
    #reviews-section .reviews-carousel-container {
        overflow: hidden;
        width: 100%;
        margin-top: 10px;
    }
    #reviews-section .reviews-track {
        display: flex;
        gap: 20px;
        transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1);
        will-change: transform;
    }
    #reviews-section .review-dark-card {
        flex: 0 0 calc((100% - 40px) / 3);
        min-width: 0;
        background: #19335A;
        border-radius: 40px 40px 40px 0;
        padding: 28px 24px 26px;
        display: flex;
        flex-direction: column;
        box-shadow: 0 8px 24px rgba(17, 53, 99, 0.12);
        box-sizing: border-box;
        transition: transform 0.25s ease, box-shadow 0.25s ease;
    }
    #reviews-section .review-dark-card:hover {
        transform: translateY(-4px);
        box-shadow: 0 14px 32px rgba(17, 53, 99, 0.22);
    }
    #reviews-section .review-card-top {
        display: flex;
        align-items: center;
        gap: 14px;
        margin-bottom: 18px;
    }
    #reviews-section .review-avatar-initial {
        width: 52px;
        height: 52px;
        border-radius: 50%;
        border: 2.5px solid #ffffff;
        color: #ffffff;
        font-size: 22px;
        font-weight: 700;
        display: flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
    }
    #reviews-section .review-user-name {
        color: #ffffff;
        font-size: 16.5px;
        font-weight: 700;
        margin: 6px 0 0;
        line-height: 1.25;
    }
    #reviews-section .review-quote-text {
        color: #cbd5e1;
        font-size: 13.5px;
        line-height: 1.65;
        margin: 0 0 20px;
        flex-grow: 1;
    }
    #reviews-section .review-view-more {
        color: #ffffff;
        font-size: 13.5px;
        font-weight: 700;
        text-decoration: underline;
        text-underline-offset: 4px;
        display: inline-flex;
        align-items: center;
        gap: 6px;
        transition: color 0.2s ease;
        align-self: flex-start;
    }
    #reviews-section .review-view-more:hover {
        color: #93c5fd;
    }
    #reviews-section .reviews-pagination-dots {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 10px;
        margin-top: 26px;
    }
    #reviews-section .review-dot {
        width: 10px;
        height: 10px;
        border-radius: 50%;
        border: 1.5px solid #19335A;
        background: transparent;
        padding: 0;
        cursor: pointer;
        transition: all 0.25s ease;
    }
    #reviews-section .review-dot.active {
        background: #19335A;
        transform: scale(1.15);
    }
    @media (max-width: 1024px) {
        #reviews-section .review-dark-card {
            flex: 0 0 calc((100% - 20px) / 2);
        }
    }
    @media (max-width: 600px) {
        #reviews-section .reviews-top-bar {
            flex-direction: column;
            align-items: flex-start;
            gap: 16px;
        }
        #reviews-section .reviews-title {
            font-size: 24px;
        }
        #reviews-section .reviews-nav-arrows {
            align-self: flex-end;
        }
        #reviews-section .review-dark-card {
            flex: 0 0 100%;
        }
    }
    </style>

