    <script>
    (function () {
        function setupReviewsCarousel() {
            const track = document.getElementById('reviewsTrack');
            const prevBtn = document.getElementById('reviewPrev');
            const nextBtn = document.getElementById('reviewNext');
            const dots = Array.from(document.querySelectorAll('#reviewsPaginationDots .review-dot'));
            if (!track) return;

            const originalCards = Array.from(track.querySelectorAll('.review-dark-card:not(.carousel-clone)'));
            const N = originalCards.length;
            if (N <= 1) return;

            // Clone cards for seamless infinite wrapping
            const prependFrag = document.createDocumentFragment();
            originalCards.forEach(card => {
                const clone = card.cloneNode(true);
                clone.classList.add('carousel-clone', 'clone-prepend');
                prependFrag.appendChild(clone);
            });
            track.insertBefore(prependFrag, originalCards[0]);

            const appendFrag = document.createDocumentFragment();
            originalCards.forEach(card => {
                const clone = card.cloneNode(true);
                clone.classList.add('carousel-clone', 'clone-append');
                appendFrag.appendChild(clone);
            });
            track.appendChild(appendFrag);

            let currentIndex = 0;
            let lastTime = 0;
            const throttleMs = 120;
            let fallbackTimer = null;

            function getStep() {
                const children = track.children;
                if (children.length > N + 1) {
                    const r0 = children[N].getBoundingClientRect();
                    const r1 = children[N + 1].getBoundingClientRect();
                    const diff = r1.left - r0.left;
                    if (diff > 0) return diff;
                }
                const first = track.querySelector('.review-dark-card');
                return first ? (first.getBoundingClientRect().width + 20) : 380;
            }

            function updateDots(idx) {
                if (!dots.length) return;
                const norm = ((idx % N) + N) % N;
                const segSize = Math.ceil(N / dots.length);
                const activeIdx = Math.min(Math.floor(norm / segSize), dots.length - 1);
                dots.forEach((d, i) => d.classList.toggle('active', i === activeIdx));
            }

            function applyPosition(animated) {
                if (animated) {
                    track.style.transition = 'transform 0.4s cubic-bezier(0.25, 1, 0.5, 1)';
                } else {
                    track.style.transition = 'none';
                }
                const step = getStep();
                const shift = (N + currentIndex) * step;
                track.style.transform = `translateX(-${shift}px)`;
                if (!animated) {
                    void track.offsetHeight;
                }
            }

            function checkWrap() {
                clearTimeout(fallbackTimer);
                const norm = ((currentIndex % N) + N) % N;
                if (currentIndex !== norm) {
                    track.style.transition = 'none';
                    currentIndex = norm;
                    const step = getStep();
                    track.style.transform = `translateX(-${(N + currentIndex) * step}px)`;
                    void track.offsetHeight;
                    track.style.transition = '';
                }
                updateDots(currentIndex);
            }

            function move(dir) {
                const now = Date.now();
                if (now - lastTime < throttleMs) return;
                lastTime = now;
                currentIndex += dir;
                applyPosition(true);
                updateDots(currentIndex);
                clearTimeout(fallbackTimer);
                fallbackTimer = setTimeout(checkWrap, 480);
            }

            nextBtn && nextBtn.addEventListener('click', (e) => { e.preventDefault(); move(1); });
            prevBtn && prevBtn.addEventListener('click', (e) => { e.preventDefault(); move(-1); });

            track.addEventListener('transitionend', (e) => {
                if (e.target === track && e.propertyName === 'transform') {
                    checkWrap();
                }
            });

            dots.forEach((dot) => {
                dot.addEventListener('click', (e) => {
                    e.preventDefault();
                    const dIdx = parseInt(dot.getAttribute('data-index') || '0', 10);
                    const segSize = Math.ceil(N / dots.length);
                    const targetCard = Math.min(dIdx * segSize, N - 1);
                    const currNorm = ((currentIndex % N) + N) % N;
                    let delta = targetCard - currNorm;
                    if (delta > N / 2) delta -= N;
                    if (delta < -N / 2) delta += N;
                    currentIndex += delta;
                    applyPosition(true);
                    updateDots(currentIndex);
                });
            });

            // Touch swipe support
            let startX = 0, startY = 0;
            track.addEventListener('touchstart', (e) => {
                if (!e.touches || !e.touches[0]) return;
                startX = e.touches[0].clientX;
                startY = e.touches[0].clientY;
            }, { passive: true });

            track.addEventListener('touchend', (e) => {
                if (!e.changedTouches || !e.changedTouches[0]) return;
                const diffX = e.changedTouches[0].clientX - startX;
                const diffY = e.changedTouches[0].clientY - startY;
                if (Math.abs(diffX) > 40 && Math.abs(diffX) > Math.abs(diffY)) {
                    move(diffX < 0 ? 1 : -1);
                }
            }, { passive: true });

            window.addEventListener('resize', () => applyPosition(false));
            applyPosition(false);
            updateDots(0);
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', setupReviewsCarousel);
        } else {
            setupReviewsCarousel();
        }
    })();
    </script>

