<script>
(function () {
    function initStickyFaqCard() {
        const faqSection = document.querySelector('.faq-section');
        const leftCol = faqSection ? faqSection.querySelector('.col-lg-6:first-child') : null;
        const card = leftCol ? leftCol.querySelector('.still-have-questions') : null;

        if (!faqSection || !leftCol || !card) return;

        card.classList.add('faq-sticky-card');

        function updateCardPosition() {
            if (window.innerWidth < 992) {
                card.style.transform = 'translateY(0px)';
                return;
            }

            const headerOffset = 130;
            const colRect = leftCol.getBoundingClientRect();
            const cardHeight = card.offsetHeight;
            const maxTravel = leftCol.offsetHeight - cardHeight;

            if (maxTravel <= 0) {
                card.style.transform = 'translateY(0px)';
                return;
            }

            let scrollOffset = headerOffset - colRect.top;
            scrollOffset = Math.max(0, Math.min(scrollOffset, maxTravel));
            card.style.transform = `translateY(${scrollOffset}px)`;
        }

        window.addEventListener('scroll', updateCardPosition, { passive: true });
        window.addEventListener('resize', updateCardPosition);
        updateCardPosition();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initStickyFaqCard);
    } else {
        initStickyFaqCard();
    }
})();
</script>
-->


    <!-- Global Single-Open FAQ Accordion (Across All Tabs) -->
    <script>
    (function() {
        function initGlobalFaqAccordion() {
            const faqMenu = document.querySelector('.faq-section .faq-menu');
            if (!faqMenu || faqMenu.dataset.faqAccordionInit === 'true') {
                return;
            }
            faqMenu.dataset.faqAccordionInit = 'true';

            const panels = Array.from(faqMenu.querySelectorAll('.accordion-collapse'));
            const buttons = Array.from(faqMenu.querySelectorAll('.accordion-button'));
            const tabButtons = Array.from(faqMenu.querySelectorAll('#myTab [data-bs-toggle="tab"]'));

            function getTriggerForPanel(panel) {
                if (!panel || !panel.id) {
                    return null;
                }
                const targetSelector = '#' + panel.id;
                return buttons.find((btn) => btn.getAttribute('data-bs-target') === targetSelector) || null;
            }

            function syncTriggerState(panel, isOpen) {
                const trigger = getTriggerForPanel(panel);
                if (!trigger) {
                    return;
                }
                trigger.classList.toggle('collapsed', !isOpen);
                trigger.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
            }

            function collapseImmediately(panel) {
                if (!panel) {
                    return;
                }
                const instance = window.bootstrap && window.bootstrap.Collapse
                    ? window.bootstrap.Collapse.getInstance(panel)
                    : null;
                if (instance) {
                    instance._isTransitioning = false;
                }
                panel.classList.remove('show', 'collapsing');
                panel.classList.add('collapse');
                panel.style.height = '';
                syncTriggerState(panel, false);
            }

            function closePanel(panel) {
                if (!panel) {
                    return;
                }
                syncTriggerState(panel, false);

                const pane = panel.closest('.tab-pane');
                const isPaneVisible = pane && pane.classList.contains('active') && pane.classList.contains('show');

                if (!isPaneVisible || !(window.bootstrap && window.bootstrap.Collapse)) {
                    collapseImmediately(panel);
                    return;
                }

                const instance = window.bootstrap.Collapse.getOrCreateInstance(panel, { toggle: false });

                if (instance._isTransitioning || panel.classList.contains('collapsing')) {
                    collapseImmediately(panel);
                    return;
                }

                if (panel.classList.contains('show')) {
                    instance.hide();
                } else {
                    collapseImmediately(panel);
                }
            }

            let activeFaqPanel = panels.find((panel) => {
                const pane = panel.closest('.tab-pane');
                return panel.classList.contains('show') && pane && pane.classList.contains('active');
            }) || null;

            panels.forEach((panel) => {
                if (panel === activeFaqPanel) {
                    syncTriggerState(panel, true);
                } else {
                    collapseImmediately(panel);
                }
            });

            faqMenu.addEventListener('show.bs.collapse', function(event) {
                const target = event.target;
                if (!target || !target.classList || !target.classList.contains('accordion-collapse')) {
                    return;
                }

                activeFaqPanel = target;
                syncTriggerState(target, true);

                panels.forEach((panel) => {
                    if (panel === target) {
                        return;
                    }
                    if (panel.classList.contains('show') || panel.classList.contains('collapsing')) {
                        closePanel(panel);
                    } else {
                        syncTriggerState(panel, false);
                    }
                });
            });

            faqMenu.addEventListener('shown.bs.collapse', function(event) {
                const target = event.target;
                if (!target || !target.classList || !target.classList.contains('accordion-collapse')) {
                    return;
                }

                if (target !== activeFaqPanel) {
                    collapseImmediately(target);
                    return;
                }

                syncTriggerState(target, true);
            });

            faqMenu.addEventListener('hide.bs.collapse', function(event) {
                const target = event.target;
                if (!target || !target.classList || !target.classList.contains('accordion-collapse')) {
                    return;
                }

                if (target === activeFaqPanel) {
                    activeFaqPanel = null;
                }
                syncTriggerState(target, false);
            });

            faqMenu.addEventListener('hidden.bs.collapse', function(event) {
                const target = event.target;
                if (!target || !target.classList || !target.classList.contains('accordion-collapse')) {
                    return;
                }

                if (target !== activeFaqPanel) {
                    syncTriggerState(target, false);
                }
            });

            tabButtons.forEach((tabBtn) => {
                tabBtn.addEventListener('show.bs.tab', function(event) {
                    const targetSelector = event.target.getAttribute('data-bs-target');
                    const incomingPane = targetSelector ? faqMenu.querySelector(targetSelector) : null;

                    if (incomingPane) {
                        Array.from(incomingPane.querySelectorAll('.accordion-collapse')).forEach(collapseImmediately);
                        const accordionBox = incomingPane.querySelector('.accordion');
                        if (accordionBox) {
                            accordionBox.scrollTop = 0;
                        }
                    }

                    activeFaqPanel = null;
                    panels.forEach(collapseImmediately);
                });

                tabBtn.addEventListener('shown.bs.tab', function(event) {
                    const targetSelector = event.target.getAttribute('data-bs-target');
                    const activePane = targetSelector ? faqMenu.querySelector(targetSelector) : null;

                    activeFaqPanel = null;
                    panels.forEach(collapseImmediately);

                    if (activePane) {
                        const accordionBox = activePane.querySelector('.accordion');
                        if (accordionBox) {
                            accordionBox.scrollTop = 0;
                        }
                    }
                });
            });
        }

        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initGlobalFaqAccordion);
        } else {
            initGlobalFaqAccordion();
        }
    })();
    </script>

